def CH(t,x,qs): return dict(sec=[t,x],qs=qs)
CHEZ={
1:CH("Chez ADI : votre titre d'habilitation","Pour le métier d'installateur et de mainteneur de SSI, la fiche du titre professionnel prévoit des habilitations de l'employeur aux niveaux B2(V), B2(V) Essais, BR, BC et H0, limitées aux installations de sécurité incendie [S41]. Votre titre dépend pourtant de vos opérations réelles, que votre employeur décrit dans son cahier des charges [S29]. Une habilitation ne vaut que pour les opérations et l'environnement indiqués dans votre titre [S29, R].",
 [Q("A01-01","s","Pour un technicien SSI, qui délivre l'habilitation ?",["Son employeur","Le formateur","Le fabricant de la centrale"],0,"L'employeur délivre l'habilitation après l'avis du formateur [S29]."),
  Q("A01-02","s","Une habilitation couvre :",["Les opérations et l'environnement indiqués dans le titre","Tout chantier de l'entreprise","Toutes les tensions"],0,"Le titre précise les opérations et limites autorisées [S29, R].")]),
2:CH("Chez ADI : où rencontrer le danger dans une centrale","Sur une installation de sécurité incendie, le danger électrique se rencontre à l'armoire de la centrale, à son alimentation en basse tension et à sa batterie [S41, S44]. Les circuits de détection sont en très basse tension, mais l'alimentation de la centrale et celle des DAS ne se jugent pas sur l'apparence [R]. Une batterie reste une source d'énergie après la coupure du secteur [S44, R].",
 [Q("A02-01","s","Où se situe le danger électrique d'une centrale d'alarme ?",["À l'alimentation de la centrale et à sa batterie","Uniquement dans les détecteurs","Nulle part"],0,"Le référentiel couvre les alimentations basse tension des SSI [S41, R]."),
  Q("A02-02","s","Un équipement en très basse tension est :",["À aborder avec méthode : la source reste à identifier","Toujours sans danger","Interdit aux techniciens"],0,"La batterie reste une source ; l'identification précède l'intervention [S44, R].")]),
3:CH("Chez ADI : qui fait quoi autour d'un SSI","Autour d'un SSI, le mainteneur agit sous contrat avec l'exploitant, qui tient le registre de sécurité et le dossier technique du système [S46]. Le technicien consigne chaque intervention dans les fiches de maintenance et d'intervention [S46]. Avant de toucher à une alimentation, il informe l'exploitant des parties du système qui seront hors service [S46, R].",
 [Q("A03-01","s","Quel document consigne vos interventions sur un SSI ?",["Les fiches d'intervention et de maintenance","Le planning des congés","Aucun document"],0,"Fiches de maintenance et fiches d'intervention [S46]."),
  Q("A03-02","s","Avant de mettre une partie du SSI hors service, que fait-on ?",["On informe l'exploitant et on met en place des mesures compensatoires","On coupe sans prévenir","On attend la nuit"],0,"Mesures compensatoires et information de l'exploitant [S46, R].")]),
4:CH("Chez ADI : zones d'un chantier SSI","Les opérations d'ADI se déroulent dans des locaux techniques, des armoires, des faux-plafonds et des circulations où passent aussi d'autres câbles [R]. Avant de commencer, identifier la nature et la tension des câbles voisins de ceux de la détection ou de l'alimentation de la centrale [R]. Tout travail près de conducteurs nus ou de tableaux ouverts se prépare avec les distances de la zone d'environnement [S29, R].",
 [Q("A04-01","s","Dans un faux-plafond, que faut-il identifier avant de remplacer un détecteur ?",["La nature et la tension des câbles voisins","La couleur du plafond","Rien"],0,"Le risque vient aussi des câbles voisins [R]."),
  Q("A04-02","s","Où sont fixées les distances d'approche ?",["Par la zone d'environnement","Par l'ancienneté du technicien","Par le client"],0,"Les zones d'environnement fixent les distances [S29].")]),
5:CH("Chez ADI : l'intervention élémentaire sur un SSI","Dans le métier, des opérations simples comme remplacer un détecteur, un diffuseur ou une batterie de petite capacité sont à examiner comme interventions élémentaires dans les limites du BS [S29, R]. Dans chaque cas, c'est l'opération telle qu'elle est décrite par l'employeur qui compte, pas le matériel [S29]. Dès qu'il faut chercher la cause d'un défaut, l'opération dépasse l'élémentaire [S29].",
 [Q("A05-01","s","Remplacer un détecteur en très basse tension relève :",["D'une opération à situer dans les limites du BS avec l'employeur","Toujours du BR","Toujours du B2"],0,"Intervention élémentaire à confirmer avec l'employeur [S29, R]."),
  Q("A05-02","s","Que faire quand il faut chercher la cause d'un défaut ?",["S'arrêter et demander le relais si le BS ne suffit pas","Continuer","Ignorer le défaut"],0,"La recherche de panne dépasse l'élémentaire [S29].")]),
6:CH("Chez ADI : mettre hors tension une centrale et son AES","Mettre hors tension une ECS ne se limite pas à couper le secteur : l'AES et sa batterie sont à traiter aussi [S44, R]. Les installations alimentées par une AES comprennent le SSI et l'éclairage de sécurité [S44]. Avant d'intervenir, repérer chaque source, puis vérifier l'absence de tension à l'endroit où l'on travaille [R].",
 [Q("A06-01","s","Que doit-on traiter pour mettre une ECS hors tension ?",["Le secteur et la batterie d'AES","Seulement le secteur","Seulement les détecteurs"],0,"L'AES maintient le SSI en service [S44, R]."),
  Q("A06-02","s","Avant d'intervenir sur une alimentation, on :",["Repère les sources puis vérifie l'absence de tension","Fait confiance au voyant","Touche pour tester"],0,"Identifier et vérifier [R].")]),
7:CH("Chez ADI : manœuvres et essais sur un SSI","Mettre un secteur du SSI en veille, déclencher un détecteur pour tester un asservissement ou actionner un déclencheur manuel sont des gestes de métier [S48]. Ils produisent des effets sur le bâtiment (alarme, portes, désenfumage) qu'il faut annoncer à l'exploitant [S48, R]. Une partie du système hors service impose des mesures compensatoires [S46].",
 [Q("A07-01","s","Un essai d'asservissement déclenche :",["Des effets réels sur le bâtiment à annoncer à l'exploitant","Rien","Un simple voyant"],0,"Les asservissements se vérifient par déclenchement de détecteurs [S48, R]."),
  Q("A07-02","s","Pourquoi annoncer un essai à l'exploitant ?",["Pour éviter une confusion avec une alarme réelle","Pour gagner du temps","Pour obtenir un symbole"],0,"Les essais ont des effets réels dans le bâtiment [S48, R].")]),
8:CH("Chez ADI : un essai ou une vraie alarme ?","Pendant une vérification, un déclenchement volontaire ne doit jamais être confondu avec un incendie réel : on prévient l'exploitant avant et après l'essai [R]. En cas d'accident électrique, on applique la conduite des secours : protéger, alerter, secourir [S31]. Si le SSI est partiellement hors service, des mesures compensatoires protègent les occupants [S46].",
 [Q("A08-01","s","Que faire avant un essai de déclenchement ?",["Prévenir l'exploitant","Rien","Couper l'alarme du bâtiment sans prévenir"],0,"Éviter toute confusion avec une alarme réelle [R]."),
  Q("A08-02","s","Quelle est la conduite en cas d'accident électrique ?",["Protéger, alerter, secourir","Toucher la victime","Attendre"],0,"Les trois actions de l'INRS [S31].")]),
9:CH("Chez ADI : installer un SSI neuf, travaux hors tension","Pour la pose de câbles, de détecteurs ou d'une centrale dans un bâtiment neuf, le référentiel du métier prévoit B2(V) pour diriger des travaux hors tension [S41]. Le chargé de travaux prépare l'opération, donne les instructions de sécurité et surveille les exécutants [S29]. Les règles d'installation des SSI, distinctes des règles de maintenance, complètent ces dispositions [S45, R].",
 [Q("A09-01","s","Qui dirige des travaux hors tension en basse tension ?",["Le chargé de travaux (B2)","L'exécutant (B1)","Le client"],0,"B2 dirige, B1 exécute [S29]."),
  Q("A09-02","s","Les règles d'installation d'un SSI sont-elles identiques aux règles de maintenance ?",["Non, ce sont des textes différents","Oui, un seul texte","Elles n'existent pas"],0,"La norme NF S 61-933 ne traite pas des modifications et extensions, qui relèvent des règles d'installation [S45].")]),
10:CH("Chez ADI : dépannage et maintenance corrective","La maintenance corrective d'un SSI est une activité centrale du métier : le référentiel la prévoit explicitement avec une habilitation BR [S41]. Dans les limites du BR, le technicien recherche la panne, remplace le matériel défectueux et rend compte [S29]. Les consignes du fabricant de la centrale complètent le titre [R].",
 [Q("A10-01","s","La maintenance corrective d'un SSI relève du métier avec :",["Une habilitation BR dans les limites du titre","Aucune habilitation","H2"],0,"Le référentiel prévoit BR pour la maintenance corrective [S41]."),
  Q("A10-02","s","Que complètent les consignes du fabricant ?",["Le titre d'habilitation, sans le remplacer","Le code du travail","La norme NF C 18-510"],0,"Les consignes du fabricant n'ajoutent pas de droit [R].")]),
11:CH("Chez ADI : consigner le départ d'une centrale ou d'une AES","Consigner l'alimentation d'une centrale ou d'une AES est une opération de consignation, dans les limites d'un titre BC [S41, S29]. Elle s'applique au départ qui alimente l'ECS, mais ne traite pas à elle seule la batterie qui continue d'alimenter le système [S44, R]. La déconsignation se fait dans l'ordre, après vérification que l'installation peut être remise en service [S29].",
 [Q("A11-01","s","Quel titre couvre la consignation du départ d'une centrale ?",["BC, dans ses limites","B0","H0V"],0,"BC est prévu au référentiel du métier [S41]."),
  Q("A11-02","s","La consignation du départ traite-t-elle la batterie ?",["Non, la batterie est à traiter à part","Oui, automatiquement","Elle n'existe pas"],0,"La batterie reste une source [S44, R].")]),
12:CH("Chez ADI : les installations HT ne sont pas au cœur du métier","Le référentiel du métier ne prévoit qu'un niveau H0 dans le domaine haute tension : le technicien SSI n'effectue pas d'opération HT [S41]. Il peut néanmoins rencontrer des postes HT dans l'environnement de certains établissements [R]. Les symboles H1, H2 sont alors à réserver à d'autres spécialistes [S29, R].",
 [Q("A12-01","s","Quel niveau HT le référentiel du métier prévoit-il ?",["H0 seulement","H1 et H2","HC"],0,"Seul H0 figure dans la liste du métier [S41]."),
  Q("A12-02","s","Si un SSI se trouve dans un poste HT, que faire ?",["S'en tenir aux opérations couvertes par le titre et demander l'avis de l'employeur","Intervenir quand même","Couper le poste"],0,"Les symboles HT sont à réserver à d'autres spécialistes [S29, R].")]),
13:CH("Chez ADI : la consignation HC reste hors métier","Le référentiel du métier ne prévoit pas de consignation HC : cette opération est réservée à des spécialistes de la HT [S41, R]. Si un SSI est alimenté depuis un poste HT, le départ concerné se consigne par un tiers habilité [R].",
 [Q("A13-01","s","Un technicien SSI consigne-t-il un départ HT ?",["Non, c'est réservé à d'autres spécialistes habilités","Oui","Seulement le soir"],0,"HC ne figure pas au référentiel [S41, R]."),
  Q("A13-02","s","Qui consigne un poste HT alimentant un SSI ?",["Un tiers habilité HC","Le technicien SSI","Le client"],0,"Opération HT à confier à un tiers habilité [R].")]),
14:CH("Chez ADI : manœuvres HT hors métier","La manœuvre d'ouvrages HT ne fait pas partie des symboles du métier [S41, R]. Pour un SSI, on se limite aux dispositifs de coupure de la basse tension qui alimente le système [S41, R].",
 [Q("A14-01","s","Manœuvre-t-on des ouvrages HT dans le métier ?",["Non, le référentiel s'arrête au domaine basse tension et à H0","Oui","Seulement HE"],0,"Seul H0 est prévu côté HT [S41]."),
  Q("A14-02","s","Quels dispositifs de coupure concernent le SSI ?",["Ceux de la basse tension qui l'alimente","Ceux du réseau HT","Aucun"],0,"Les alimentations basse tension des SSI [S41, R].")]),
15:CH("Chez ADI : mesurer, vérifier et essayer sur un SSI","Le référentiel du métier prévoit l'habilitation B2(V) Essais pour les mesurages, vérifications et essais [S41]. Une vérification annuelle comprend l'inspection de l'ECS, des détecteurs, des organes reliés, des diffuseurs sonores, de l'alimentation et de la batterie d'AES [S49, S48]. Chaque mesure s'accompagne de la vérification du bon fonctionnement de l'appareil de mesure avant et après usage [R].",
 [Q("A15-01","s","Quel attribut est prévu pour les essais dans le métier ?",["B2(V) Essais","H2","HE"],0,"Titre prévu au référentiel [S41]."),
  Q("A15-02","s","Que vérifie-t-on sur l'alimentation d'un SSI ?",["L'alimentation et la batterie d'AES","Le mobilier","La peinture"],0,"Inspection annuelle de l'alimentation et de la batterie [S49].")]),
16:CH("Chez ADI : une pratique sur une centrale et son alimentation","Les savoir-faire se pratiquent de préférence dans un environnement proche du réel, sur des installations représentatives [S29]. Pour ADI, cela suggère une centrale ou une ECS avec batterie, un déclencheur manuel et un détecteur, sur lesquels chaque stagiaire opère lui-même [S29, R]. Le matériel de la session sera à confirmer avec ADI avant décembre [R].",
 [Q("A16-01","s","Sur quel support vaut-il mieux s'exercer ?",["Une installation proche du réel, comme une centrale avec batterie","Un dessin au tableau","Aucun support"],0,"Environnement proche du réel [S29]."),
  Q("A16-02","s","Qui opère lors de la pratique d'un module spécifique ?",["Chaque stagiaire lui-même","Le formateur seul","Un seul volontaire"],0,"L'apprenant réalise lui-même les opérations [S29].")]),
18:CH("Chez ADI : zones et voisinage dans un local technique","En local technique, la proximité de pièces nues sous tension, de tableaux ouverts et de câbles se juge avant d'ouvrir l'armoire de la centrale [R]. Le voisinage renforcé (V) impose des dispositions supplémentaires et le titre doit l'indiquer [S29].",
 [Q("A18-01","s","Que signale la lettre V ?",["Le voisinage renforcé","La vitesse","La ventilation"],0,"La lettre V désigne le voisinage renforcé [S29]."),
  Q("A18-02","s","Que juger avant d'ouvrir l'armoire d'une centrale en local technique ?",["Les pièces nues voisines et les tableaux ouverts","La couleur de l'armoire","Rien"],0,"Le voisinage se juge avant d'ouvrir [R].")]),
19:CH("Chez ADI : reconnaître l'appareillage d'une alimentation de centrale","Les armoires d'alimentation des centrales contiennent des protections, des borniers et des batteries : savoir les reconnaître évite de prendre un élément pour un autre [R]. Le repérage des circuits et des synoptiques mis à jour fait partie des attentes d'un donneur d'ordre [S48].",
 [Q("A19-01","s","Que demande un donneur d'ordre à propos des synoptiques ?",["Qu'ils soient à jour","Qu'ils soient cachés","Rien"],0,"Synoptiques et schémas à jour [S48]."),
  Q("A19-02","s","Pourquoi reconnaître l'appareillage d'une alimentation de centrale ?",["Pour ne pas prendre un élément pour un autre","Pour le décorer","Pour le vendre"],0,"Éviter les confusions avant d'intervenir [R].")]),
21:CH("Chez ADI : remplacer un élément d'alimentation ou une batterie","Remplacer une batterie ou un élément d'alimentation d'ECS suit la même logique que le remplacement d'un appareillage : identifier la source, mettre hors tension, remplacer à l'identique, essayer et consigner [S44, S48, R]. Si le remplacement impose de modifier le circuit, l'opération dépasse le simple remplacement [R].",
 [Q("A21-01","s","Que fait-on après le remplacement d'une batterie ?",["On essaie et on consigne","On repart sans essai","On cache la batterie"],0,"Essai et compte rendu [S48]."),
  Q("A21-02","s","Que faire si le remplacement impose de modifier le circuit ?",["Considérer que l'opération dépasse le simple remplacement","Continuer sans réfléchir","Ignorer"],0,"Modification : hors périmètre du simple remplacement [R].")]),
}
VALEURS_ADI['000']=('D','distracteur : 10 000 à 20 000 V')
